public interface DataGateway {
    void persist(ByteBuffer buffer) throws DataTransferException;
}

public class ChannelDataGateway implements DataGateway {
    private final AsynchronousFileChannel fileChannel;

    public ChannelDataGateway(AsynchronousFileChannel fileChannel) {
        this.fileChannel = fileChannel;
    }

    @Override
    public void persist(ByteBuffer buffer) {
        fileChannel.write(buffer, 0, buffer, new CompletionHandler<Integer, ByteBuffer>() {
            @Override
            public void completed(Integer result, ByteBuffer attachment) {
                attachment.clear();
            }

            @Override
            public void failed(Throwable exc, ByteBuffer attachment) {
                throw new DataTransferException("Failed to write bytes via NIO", exc);
            }
        });
    }
}
